//! Settings compatibility with files the Python app wrote (fixtures generated by
//! `tools/gen_settings_fixtures.py`, synthetic values only) and the one-way migration.

use serde_json::{json, Value};
use stagepilot_core::config::MidiSource;
use stagepilot_core::settings::*;
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name)
}

fn staged(dir: &tempfile::TempDir, name: &str) -> PathBuf {
    let target = dir.path().join("settings.json");
    std::fs::copy(fixture(name), &target).unwrap();
    target
}

fn read(path: &Path) -> Value {
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

#[test]
fn python_written_v2_file_loads_unchanged() {
    let dir = tempfile::tempdir().unwrap();
    let path = staged(&dir, "python_written_v2.json");
    let store = SettingsFileStore::new(&path);
    let settings = store.load().unwrap().unwrap();
    assert_eq!(settings.timezone, "America/Chicago");
    assert_eq!(settings.server_port, 9123);
    assert!(settings.lan_access);
    assert!(settings.web_dashboard_pin_hash.is_some());
    // Loading a current file never rewrites it and never makes a backup.
    assert!(!store.backup_path().exists());
}

#[test]
fn rust_save_round_trips_through_the_python_schema() {
    let dir = tempfile::tempdir().unwrap();
    let path = staged(&dir, "python_written_v2.json");
    let before = read(&path);
    let store = SettingsFileStore::new(&path);
    let settings = store.load().unwrap().unwrap();
    store.save(&settings).unwrap();
    // The Python-written JSON and the Rust-written JSON are the same document.
    assert_eq!(read(&path), before);
}

#[test]
fn first_write_makes_a_backup_copy_once() {
    let dir = tempfile::tempdir().unwrap();
    let path = staged(&dir, "python_written_v2.json");
    let original = std::fs::read(&path).unwrap();
    let store = SettingsFileStore::new(&path);
    let mut settings = store.load().unwrap().unwrap();
    settings.timezone = "UTC".into();
    store.save(&settings).unwrap();
    assert_eq!(std::fs::read(store.backup_path()).unwrap(), original);
    settings.timezone = "America/Denver".into();
    store.save(&settings).unwrap();
    // A second write (or a new process) never overwrites the first backup.
    assert_eq!(std::fs::read(store.backup_path()).unwrap(), original);
    let again = SettingsFileStore::new(&path);
    again.save(&settings).unwrap();
    assert_eq!(std::fs::read(again.backup_path()).unwrap(), original);
}

#[test]
fn v1_untouched_install_moves_to_playback_and_rewrites_the_file() {
    let dir = tempfile::tempdir().unwrap();
    let path = staged(&dir, "python_v1_untouched.json");
    let store = SettingsFileStore::new(&path);
    let settings = store.load().unwrap().unwrap();
    assert_eq!(
        settings.integration_modes.midi_source,
        MidiSource::PlaybackApi
    );
    assert_eq!(settings.schema_version, 2);
    assert_eq!(settings.timezone, "America/Denver");
    // M4: loading never writes; the migrated file is written by the next save.
    assert!(!store.backup_path().exists());
    store.save(&settings).unwrap();
    let written = read(&path);
    assert_eq!(written["schema_version"], 2);
    assert_eq!(written["integration_modes"]["midi_source"], "playback_api");
    // The legacy key is gone from the migrated file, and the v1 original is kept aside.
    assert!(written.get("release_channel").is_none());
    assert!(store.backup_path().exists());
    assert_eq!(read(&store.backup_path())["release_channel"], "beta");
}

#[test]
fn v1_explicit_midi_choice_is_kept() {
    let dir = tempfile::tempdir().unwrap();
    let path = staged(&dir, "python_v1_midi_chosen.json");
    let settings = SettingsFileStore::new(&path).load().unwrap().unwrap();
    assert_eq!(settings.integration_modes.midi_source, MidiSource::Real);
    assert_eq!(
        settings.midi.input_name.as_deref(),
        Some("Synthetic MIDI Port 1")
    );
}

#[test]
fn migration_is_one_way_and_idempotent() {
    let dir = tempfile::tempdir().unwrap();
    let path = staged(&dir, "python_v1_untouched.json");
    let store = SettingsFileStore::new(&path);
    // Loading migrates in memory only (M4: loading never writes); the next save writes it.
    let original = read(&path);
    let settings = store.load().unwrap().unwrap();
    assert_eq!(read(&path), original);
    store.save(&settings).unwrap();
    let migrated = read(&path);
    assert_ne!(migrated, original);
    // Loading the migrated file again changes nothing.
    SettingsFileStore::new(&path).load().unwrap();
    assert_eq!(read(&path), migrated);
    // migrate_v1 itself: no migration happens for a current schema.
    let (_, migration) = PersistentSettings::migrate_v1(migrated);
    assert!(migration.is_none());
}

#[test]
fn legacy_release_channel_is_dropped_on_load_and_save() {
    let dir = tempfile::tempdir().unwrap();
    let path = staged(&dir, "python_v2_release_channel.json");
    let store = SettingsFileStore::new(&path);
    let settings = store.load().unwrap().unwrap();
    store.save(&settings).unwrap();
    assert!(read(&path).get("release_channel").is_none());
}

#[test]
fn unknown_keys_are_kept_and_the_file_is_left_alone() {
    // rc.4 rejected the whole file here; M4 keeps the unknown key (see settings_loader_matrix).
    let dir = tempfile::tempdir().unwrap();
    let path = staged(&dir, "python_v2_unknown_key.json");
    let before = std::fs::read(&path).unwrap();
    let settings = SettingsFileStore::new(&path).load().unwrap();
    assert!(settings.is_some());
    assert_eq!(std::fs::read(&path).unwrap(), before);
}

#[test]
fn corrupt_json_fails_safely() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("settings.json");
    std::fs::write(&path, "{ not json").unwrap();
    assert!(SettingsFileStore::new(&path).load().is_err());
    assert_eq!(std::fs::read_to_string(&path).unwrap(), "{ not json");
}

#[test]
fn nested_unknown_key_in_planning_center_is_rejected() {
    let error =
        PersistentSettings::from_value(json!({"planning_center": {"bogus": 1}})).unwrap_err();
    assert_eq!(error[0].kind, "extra_forbidden");
    assert_eq!(error[0].loc, vec![json!("planning_center"), json!("bogus")]);
}

#[test]
fn invalid_timezone_and_port_are_rejected_with_pydantic_shapes() {
    let tz = PersistentSettings::from_value(json!({"timezone": "Not/AZone"})).unwrap_err();
    assert_eq!(tz[0].kind, "value_error");
    assert_eq!(tz[0].msg, "Value error, Unknown IANA timezone: Not/AZone");
    let port = PersistentSettings::from_value(json!({"server_port": 70000})).unwrap_err();
    assert_eq!(port[0].kind, "less_than_equal");
}

#[test]
fn pin_hash_is_stored_but_never_serialised_to_the_api() {
    let (settings, _) = PersistentSettings::from_value(json!({
        "web_dashboard_pin_hash": "pbkdf2_sha256$1$AAAA$BBBB"
    }))
    .unwrap();
    assert!(serde_json::to_value(&settings)
        .unwrap()
        .get("web_dashboard_pin_hash")
        .is_none());
    assert_eq!(
        settings.to_file_value()["web_dashboard_pin_hash"],
        "pbkdf2_sha256$1$AAAA$BBBB"
    );
}

#[test]
fn settings_path_logic_matches_python() {
    let env = |pairs: &[(&str, &str)]| -> BTreeMap<String, String> {
        pairs
            .iter()
            .map(|(k, v)| (k.to_string(), v.to_string()))
            .collect()
    };
    assert_eq!(
        default_settings_path(&env(&[("STAGEPILOT_SETTINGS_PATH", "/tmp/x/s.json")])),
        PathBuf::from("/tmp/x/s.json")
    );
    if !cfg!(windows) {
        assert_eq!(
            default_settings_path(&env(&[("XDG_CONFIG_HOME", "/tmp/cfg")])),
            PathBuf::from("/tmp/cfg/StagePilot/settings.json")
        );
        assert_eq!(
            default_settings_path(&env(&[("HOME", "/home/synthetic")])),
            PathBuf::from("/home/synthetic/.config/StagePilot/settings.json")
        );
    }
}

fn service_with(dir: &tempfile::TempDir, environ: &[(&str, &str)]) -> SettingsService {
    let environ = environ
        .iter()
        .map(|(k, v)| (k.to_string(), v.to_string()))
        .collect();
    SettingsService::new(
        Box::new(SettingsFileStore::new(dir.path().join("settings.json"))),
        Box::new(MemoryCredentialStore::default()),
        environ,
    )
}

#[test]
fn defaults_load_without_a_file_and_environment_overrides_saved_values() {
    let dir = tempfile::tempdir().unwrap();
    let service = service_with(&dir, &[("STAGEPILOT_PORT", "9999")]);
    let runtime = service.load();
    assert_eq!(runtime.bind_port, 9999);
    assert_eq!(service.snapshot().server_port, 8765);
    assert_eq!(service.effective_snapshot().server_port, 9999);
}

#[test]
fn pin_hash_survives_a_new_service_instance_and_a_settings_save() {
    let dir = tempfile::tempdir().unwrap();
    let first = service_with(&dir, &[]);
    first.load();
    first
        .update_dashboard_access(true, Some("pbkdf2_sha256$1$AAAA$BBBB".into()))
        .unwrap();
    // A later settings save without a hash keeps the stored hash.
    let mut changed = first.snapshot();
    changed.web_dashboard_pin_hash = None;
    changed.timezone = "UTC".into();
    first.save(changed).unwrap();
    let second = service_with(&dir, &[]);
    second.load();
    assert_eq!(
        second.snapshot().web_dashboard_pin_hash.as_deref(),
        Some("pbkdf2_sha256$1$AAAA$BBBB")
    );
    assert_eq!(second.snapshot().timezone, "UTC");
}

#[test]
fn completed_general_onboarding_cannot_be_cleared_by_a_stale_save() {
    let dir = tempfile::tempdir().unwrap();
    let service = service_with(&dir, &[]);
    service.load();
    let mut done = service.snapshot();
    done.onboarding.general_completed = true;
    service.save(done).unwrap();
    let mut stale = service.snapshot();
    stale.onboarding.general_completed = false;
    service.save(stale).unwrap();
    assert!(service.snapshot().onboarding.general_completed);
}

#[test]
fn planning_center_secret_is_never_written_to_the_json_file() {
    let dir = tempfile::tempdir().unwrap();
    let service = service_with(&dir, &[]);
    service.load();
    let mut pc = service.snapshot().planning_center;
    pc.app_id = Some("synthetic-app".into());
    service
        .update_planning_center(pc, Some("synthetic-secret-value"), false)
        .unwrap();
    assert!(service.credential_saved());
    let text = std::fs::read_to_string(dir.path().join("settings.json")).unwrap();
    assert!(!text.contains("synthetic-secret-value"));
}

#[test]
fn keyring_service_and_account_names_match_python() {
    assert_eq!(KEYRING_SERVICE, "StagePilot");
    assert_eq!(KEYRING_ACCOUNT, "planning-center-secret");
    assert_eq!(KEYRING_ACCOUNT_OAUTH, "planning-center-oauth");
}

#[test]
fn environment_pins_are_reported_by_variable_name() {
    let dir = tempfile::tempdir().unwrap();
    let service = service_with(&dir, &[("STAGEPILOT_SERVICE_SOURCE", "demo")]);
    assert_eq!(
        service.service_source_pin().as_deref(),
        Some("STAGEPILOT_SERVICE_SOURCE")
    );
    assert_eq!(service.timer_output_pin(), None);
}
